/**
 * Brazil, Colombia, Mexico and Peru alert fixtures (SPEC §6, rows 1-88; review rows 89-92).
 *
 * Every body is written in Wafra's own words around the abstracted template
 * shapes described in docs/universal-parser-rollout.md. Names, merchants,
 * amounts, dates, footers and card digits are invented; a posting row shares
 * only the fixed template wording (the words the parser must match)
 * with any public description, and uses the template's alternative word order
 * or optional clauses where it has them. No row reproduces bank, open-source
 * or corpus message text (checked by an n-gram similarity scan against the
 * community corpora), and none is a consented real alert: `synthetic` rows
 * exercise a grammar edge, `community-derived` rows restate a template shape
 * that public open-source fixtures describe. No row may count toward an
 * automatic-import gate.
 *
 * Shapes:
 *   money:    { figure, parser, minor } or { body, market, currency, minor }
 *   route:    { body, sender, market | notMarkets, decision }
 *   post:     { body, market, sender, expect: { type, minor, transfer, merchant?, last4?, date?, category?, family, direction } }
 *   review:   { body, market, sender, expect: { family, direction, minor } }   — routed to Review, never posted
 *   card-payment: { body, market, sender, expect: { card, side, minor, date } } — an own card-bill payment
 *   never:    { body, market, sender, category }                              — must never post
 */

const meta = (provenance, institution, channel, template) => ({ provenance, institution, channel, template, heldOut: false });
const SYN = (institution = null, template = null, channel = 'sms') => meta('synthetic', institution, channel, template);
const COM = (institution, template, channel = 'sms') => meta('community-derived', institution, channel, template);

const money = (n, figure, parser, minor, extra = {}) => ({ n, kind: 'money', figure, parser, minor, ...SYN(), ...extra });
const route = (n, body, sender, expected, extra = {}) => ({ n, kind: 'route', body, sender, ...expected, ...SYN(), ...extra });
const post = (n, id, market, body, expect, m, sender = '') => ({ n, id, kind: 'post', market, body, sender, expect, ...m });
const review = (n, id, market, body, expect, m, sender = '') => ({ n, id, kind: 'review', market, body, sender, expect, ...m });
const never = (n, id, market, body, category, sender = '') => ({ n, id, kind: 'never', market, body, sender, category, ...SYN() });

